import pytest
import uuid


@pytest.mark.asyncio
class TestBookingAPI:

    def test_create_booking_success(self, client, sample_event, sample_seats, redis_client, mock_event_publisher):
        """Test successful booking via API"""
        user_id = str(uuid.uuid4())
        seat = sample_seats[0]

        response = client.post(
            "/api/v1/bookings/",
            json={
                "user_id": user_id,
                "event_id": str(sample_event.event_id),
                "seat_id": str(seat.seat_id)
            },
            headers={"Idempotency-Key": "api-test-123"}
        )

        assert response.status_code == 201
        data = response.json()
        assert data["success"] is True
        assert "booking_id" in data
        assert data["seat_id"] == str(seat.seat_id)

    def test_create_booking_already_booked(self, client, db, sample_event, sample_seats, redis_client,
                                           mock_event_publisher):
        """Test booking an already booked seat via API"""
        from app.models.seat import SeatStatus

        # Book the seat first
        seat = sample_seats[0]
        seat.status = SeatStatus.BOOKED
        db.commit()

        user_id = str(uuid.uuid4())

        response = client.post(
            "/api/v1/bookings/",
            json={
                "user_id": user_id,
                "event_id": str(sample_event.event_id),
                "seat_id": str(seat.seat_id)
            }
        )

        assert response.status_code == 409
        data = response.json()
        assert data["success"] is False
        assert "SEAT_ALREADY_BOOKED" in data["error_code"]

    def test_reserve_seat(self, client, sample_event, sample_seats, redis_client, mock_event_publisher):
        """Test seat reservation via API"""
        user_id = str(uuid.uuid4())
        seat = sample_seats[0]

        response = client.post(
            "/api/v1/bookings/reserve",
            json={
                "user_id": user_id,
                "event_id": str(sample_event.event_id),
                "seat_id": str(seat.seat_id)
            }
        )

        assert response.status_code == 200
        data = response.json()
        assert data["success"] is True
        assert "reserved_until" in data

    def test_get_booking(self, client, db, sample_event, sample_seats, redis_client, mock_event_publisher):
        """Test getting booking details"""
        from app.models.booking import Booking, BookingStatus, PaymentStatus

        # Create a booking
        booking = Booking(
            booking_id=uuid.uuid4(),
            user_id=uuid.uuid4(),
            event_id=sample_event.event_id,
            seat_id=sample_seats[0].seat_id,
            total_amount=100.00,
            booking_status=BookingStatus.CONFIRMED,
            payment_status=PaymentStatus.PENDING
        )
        db.add(booking)
        db.commit()

        response = client.get(f"/api/v1/bookings/{booking.booking_id}")

        assert response.status_code == 200
        data = response.json()
        assert data["booking_id"] == str(booking.booking_id)

    def test_get_user_bookings(self, client, db, sample_event, sample_seats):
        """Test getting all bookings for a user"""
        from app.models.booking import Booking, BookingStatus, PaymentStatus

        user_id = uuid.uuid4()

        # Create multiple bookings
        for i in range(3):
            booking = Booking(
                booking_id=uuid.uuid4(),
                user_id=user_id,
                event_id=sample_event.event_id,
                seat_id=sample_seats[i].seat_id,
                total_amount=100.00,
                booking_status=BookingStatus.CONFIRMED,
                payment_status=PaymentStatus.PENDING
            )
            db.add(booking)

        db.commit()

        response = client.get(f"/api/v1/bookings/user/{user_id}")

        assert response.status_code == 200
        data = response.json()
        assert len(data) == 3

    def test_rate_limiting(self, client, sample_event, sample_seats, redis_client, mock_event_publisher):
        """Test rate limiting on booking endpoint"""
        user_id = str(uuid.uuid4())

        # Make multiple requests rapidly
        for i in range(15):
            response = client.post(
                "/api/v1/bookings/",
                json={
                    "user_id": user_id,
                    "event_id": str(sample_event.event_id),
                    "seat_id": str(sample_seats[0].seat_id)
                },
                headers={"X-User-ID": user_id}
            )

            if i >= 10:
                assert response.status_code == 429
